// Package desktop is the desktop shell of Go applications generated by
// Clarity: a Wails v3 application with one Wails service, through which
// the renderer sends its commands to package shell's service. The program
// binds it as main.Clarity, the name the renderer calls. An application
// has one desktop window; a window marked `in new window` gets a second
// one. What belongs to a desktop window (its title, windows of their own,
// custom parts, links in the person's browser) is answered here.
package desktop

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"runtime"
	"strconv"

	"github.com/petervdpas/Clarity/runtimes/go/parts"
	"github.com/petervdpas/Clarity/runtimes/go/shell"

	"github.com/wailsapp/wails/v3/pkg/application"
	"github.com/wailsapp/wails/v3/pkg/events"
)

// apart is the start of a desktop window of its own: the Clarity window
// it starts with, its data, and the desktop window that opened it.
type apart struct {
	window string
	with   map[string]any
	opener string
}

// windows are the desktop windows of the application, as the service's
// commands from them need them.
type windows struct {
	service *shell.Service
	app     *application.App
	title   string
	apart   map[string]apart
	next    int
	// parts is the desktop window an open window's custom parts are in,
	// by the open window's number (DESIGN 6.5).
	parts map[uint64]string
}

// caller is the desktop window a command came from; nil without one.
func caller(ctx context.Context) application.Window {
	window, _ := ctx.Value(application.WindowKey).(application.Window)
	return window
}

// Command answers the commands of a desktop window; the service holds its lock.
func (d *windows) Command(ctx context.Context, command string, a shell.Args) (shell.Answer, bool) {
	switch command {
	case "set_title":
		if window := caller(ctx); window != nil {
			window.SetTitle(a.Title)
		}
	case "open_link":
		if err := d.app.Browser.OpenURL(a.Address); err != nil {
			return shell.Answer{Error: fmt.Sprintf("cannot open %s: %v", a.Address, err)}, true
		}
	case "quit_app":
		d.app.Quit()
	case "choose_folder":
		// The system's folder picker, for a folder part: the folder chosen, or none.
		dialog := d.app.Dialog.OpenFile().CanChooseFiles(false).CanChooseDirectories(true).SetTitle(a.Title)
		if window := caller(ctx); window != nil {
			dialog = dialog.AttachToWindow(window)
		}
		folder, err := dialog.PromptForSingleSelection()
		if err != nil {
			return shell.Answer{Error: fmt.Sprintf("cannot choose a folder: %v", err)}, true
		}
		if folder == "" {
			return shell.Answer{}, true
		}
		return shell.Answer{Value: folder}, true
	case "open_apart":
		return d.openApart(caller(ctx), a.Window, a.With, a.Width, a.Height), true
	case "apart_start":
		window := caller(ctx)
		if window == nil {
			return shell.Answer{}, true
		}
		start, ok := d.apart[window.Name()]
		if !ok {
			return shell.Answer{}, true
		}
		return shell.Answer{Value: map[string]any{"window": start.window, "with": start.with}}, true
	// Custom parts (DESIGN 6.5): where each is and what it is given, for the part host.
	case "place_part":
		var parent uintptr
		if window := caller(ctx); window != nil {
			d.parts[a.Instance] = window.Name()
			application.InvokeSync(func() { parent = partParent(window.NativeWindow()) })
		}
		parts.Place(a.Instance, a.Part, a.Kind, uint64(parent), a.X, a.Y, a.Width, a.Height, a.Shown)
	case "set_part":
		parts.Set(a.Instance, a.Part, a.Name, a.Value)
	case "hear_part":
		parts.Hear(a.Instance, a.Part, a.Hear, a.Values)
	case "close_parts":
		parts.Close(a.Instance)
		delete(d.parts, a.Instance)
	case "close_apart":
		if window := caller(ctx); window != nil {
			window.Close()
		}
	default:
		return shell.Answer{}, false
	}
	return shell.Answer{}, true
}

// size is the size a desktop window opens at: its window's, or the
// standard size when the window says none.
func size(width, height int) (int, int) {
	if width <= 0 || height <= 0 {
		return 1100, 760
	}
	return width, height
}

// window is a desktop window showing the renderer, at the size of the
// Clarity window it shows first.
func (d *windows) window(name string, width, height int) *application.WebviewWindow {
	width, height = size(width, height)
	return d.app.Window.NewWithOptions(application.WebviewWindowOptions{
		Name:   name,
		Title:  d.title,
		Width:  width,
		Height: height,
		URL:    "/",
	})
}

// openApart opens a Clarity window in a desktop window of its own, as the
// design marks it. When it closes, the window that opened it is told, so
// it can reload its data.
func (d *windows) openApart(opener application.Window, window string, with map[string]any, width, height int) shell.Answer {
	if opener == nil {
		return shell.Answer{Error: "a window of its own needs the desktop"}
	}
	d.next++
	name := fmt.Sprintf("apart-%d", d.next)
	d.apart[name] = apart{window, with, opener.Name()}
	desktop := d.window(name, width, height)
	desktop.OnWindowEvent(events.Common.WindowClosing, func(*application.WindowEvent) {
		d.service.Lock()
		start := d.apart[name]
		delete(d.apart, name)
		d.service.Unlock()
		if back, ok := d.app.Window.GetByName(start.opener); ok {
			back.ExecJS("window.dispatchEvent(new Event('clarity-return'))")
		}
	})
	return shell.Answer{}
}

// Run shows the application's window and runs until it closes. bind makes
// the Wails service of the program's own type, so its name in the renderer
// is the program's: main.Clarity.
func Run(options shell.Options, bind func(*shell.Service) application.Service) error {
	// WebKitGTK 2.52 paints parts of a new window black through its DMABUF
	// renderer; it must be off before the web process starts.
	if runtime.GOOS == "linux" && os.Getenv("WEBKIT_DISABLE_DMABUF_RENDERER") == "" {
		_ = os.Setenv("WEBKIT_DISABLE_DMABUF_RENDERER", "1")
	}
	// Custom parts draw in X11 child windows: under Wayland the toolkit runs on XWayland.
	hasParts := parts.Present()
	if hasParts && runtime.GOOS == "linux" && os.Getenv("GDK_BACKEND") == "" {
		_ = os.Setenv("GDK_BACKEND", "x11")
	}
	service := shell.New(options)
	d := &windows{service: service, title: options.Title, apart: map[string]apart{}, parts: map[uint64]string{}}
	d.app = application.New(application.Options{
		Name:     options.Name,
		Services: []application.Service{bind(service)},
		Assets:   application.AssetOptions{Handler: application.AssetFileServerFS(options.Assets)},
		Mac:      application.MacOptions{ApplicationShouldTerminateAfterLastWindowClosed: true},
	})
	service.SetDesktop(d)
	main := d.window("main", options.Width, options.Height)
	main.RegisterHook(events.Common.WindowClosing, func(e *application.WindowEvent) {
		if service.ClosesToScreen() {
			e.Cancel()
			main.ExecJS("window.clarityCloseRequested && window.clarityCloseRequested()")
		}
	})
	if hasParts {
		// A part tells on the part host's goroutine; the renderer of its window hears it.
		err := parts.Start(func(window uint64, part, tell string, given []any) {
			service.Lock()
			name, ok := d.parts[window]
			service.Unlock()
			if !ok {
				return
			}
			values, _ := json.Marshal(given)
			if desktop, found := d.app.Window.GetByName(name); found {
				desktop.ExecJS("window.clarityTold && window.clarityTold(" + strconv.FormatUint(window, 10) + ", " + quoted(part) + ", " + quoted(tell) + ", " + string(values) + ")")
			}
		})
		if err != nil {
			fmt.Fprintln(os.Stderr, err)
		}
		defer parts.Stop()
	}
	return d.app.Run()
}

// quoted is text as a JavaScript string.
func quoted(text string) string {
	out, _ := json.Marshal(text)
	return string(out)
}
